#!/usr/bin/env bash
# unityHPC/sync.sh — generated by /unity-hpc:setup. Do not hand-edit; re-run setup
# to regenerate. Any previous version is preserved under unityHPC/.pre-redesign/.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(cd "$HERE/.." && pwd)"

if [ -f "$HERE/.env" ]; then . "$HERE/.env"; elif [ -f "$PROJECT_DIR/.env" ]; then . "$PROJECT_DIR/.env"; fi
: "${UNITY_HOST:=unity}"
: "${REMOTE_DIR:?REMOTE_DIR must be set in .env}"

ssh "$UNITY_HOST" "mkdir -p ${REMOTE_DIR}"
rsync -az --delete \
    --exclude '.git/' --exclude '__pycache__/' --exclude '.venv/' \
    --exclude '_results/' --exclude '.unity_state/' --exclude '_slurm/' \
    "$PROJECT_DIR/" "${UNITY_HOST}:${REMOTE_DIR}/"
echo "Sync done."
